//! JSON frontend: build an [`ir::Model`] from a compact JSON description.
//!
//! This is useful when a model is generated by another tool rather than written
//! by hand in PSS. The schema is documented in the project README; a minimal
//! example:
//!
//! ```json
//! {
//!   "constants": { "CACHELINE": 64 },
//!   "enums": { "mem_block_e": ["SYS_MEM", "LOCAL"] },
//!   "types": {
//!     "data_buf": {
//!       "fields": [ {"name": "size", "kind": "rand", "type": "bit", "bits": 16} ],
//!       "constraints": ["size <= 1024"]
//!     }
//!   },
//!   "components": {
//!     "pss_top": {
//!       "actions": {
//!         "test": { "activity": [ {"do": "produce"} ] },
//!         "produce": {
//!           "fields": [ {"name": "size", "kind": "rand", "type": "int", "in": [1, 64]} ]
//!         }
//!       }
//!     }
//!   },
//!   "top": "pss_top"
//! }
//! ```

use std::collections::HashMap;

use crate::ast::{Activity, ActivityStmt, Expr, Path, JoinSpec};
use crate::error::{PssError, PssResult};
use crate::ir::{
    Action, Bind, Component, Constraint, DataType, Field, FieldKind, Model, Pool, TypeCategory,
};
use crate::parser::parse_expression;

/// Build a model from a JSON string.
pub fn model_from_json(src: &str) -> PssResult<Model> {
    let v = Json::parse(src)?;
    let obj = v.as_obj().ok_or_else(|| PssError::plain("top-level JSON must be an object"))?;

    let mut model = Model {
        covergroups: Vec::new(),
        monitors: Vec::new(),
        constants: HashMap::new(),
        enums: HashMap::new(),
        types: HashMap::new(),
        components: HashMap::new(),
        actions: HashMap::new(),
        packages: Vec::new(),
        top: None,
        addr_regions: Vec::new(),
        qual_index: HashMap::new(),
        duplicates: Vec::new(),
    };

    if let Some(pkgs) = obj_get(obj, "packages").and_then(|v| v.as_arr()) {
        for p in pkgs {
            if let Some(s) = p.as_str() {
                model.packages.push(s.to_string());
            }
        }
    }
    if let Some(cs) = obj_get(obj, "constants").and_then(|v| v.as_obj()) {
        for (k, val) in cs {
            if let Some(n) = val.as_i64() {
                model.constants.insert(k.clone(), n);
            }
        }
    }
    if let Some(en) = obj_get(obj, "enums").and_then(|v| v.as_obj()) {
        for (k, val) in en {
            let variants: Vec<String> = val
                .as_arr()
                .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
                .unwrap_or_default();
            model.enums.insert(k.clone(), variants);
        }
    }

    // Component names are needed to classify field types.
    let component_names: Vec<String> = obj_get(obj, "components")
        .and_then(|v| v.as_obj())
        .map(|o| o.iter().map(|(k, _)| k.clone()).collect())
        .unwrap_or_default();

    // Types. Register all names first so fields may reference each other.
    if let Some(types) = obj_get(obj, "types").and_then(|v| v.as_obj()) {
        for (name, _) in types {
            model.types.insert(
                name.clone(),
                DataType {
                    name: name.clone(),
                    keyword: "struct".into(),
                    base: None,
                    fields: Vec::new(),
                    constraints: Vec::new(),
                },
            );
        }
        for (name, tv) in types {
            let to = tv.as_obj().ok_or_else(|| PssError::plain(format!("type `{}` must be an object", name)))?;
            let fields = build_fields(to, &model.enums, &model.types, &component_names)?;
            let constraints = build_constraints(to)?;
            let base = obj_get(to, "base").and_then(|v| v.as_str()).map(|s| s.to_string());
            model.types.insert(
                name.clone(),
                DataType {
                    name: name.clone(),
                    keyword: "struct".into(),
                    base,
                    fields,
                    constraints,
                },
            );
        }
    }

    // Components and their actions.
    let mut actions: HashMap<String, Action> = HashMap::new();
    if let Some(comps) = obj_get(obj, "components").and_then(|v| v.as_obj()) {
        for (name, cv) in comps {
            let co = cv
                .as_obj()
                .ok_or_else(|| PssError::plain(format!("component `{}` must be an object", name)))?;
            let mut subcomponents = Vec::new();
            if let Some(sc) = obj_get(co, "subcomponents").and_then(|v| v.as_obj()) {
                for (inst, ty) in sc {
                    if let Some(t) = ty.as_str() {
                        subcomponents.push((inst.clone(), t.to_string()));
                    }
                }
            }
            let fields = build_fields(co, &model.enums, &model.types, &component_names)?;
            let mut action_names = Vec::new();
            if let Some(acts) = obj_get(co, "actions").and_then(|v| v.as_obj()) {
                for (aname, av) in acts {
                    let ao = av.as_obj().ok_or_else(|| {
                        PssError::plain(format!("action `{}` must be an object", aname))
                    })?;
                    let mut act_fields = build_fields(ao, &model.enums, &model.types, &component_names)?;
                    let mut constraints = build_constraints(ao)?;
                    // Fold inline ranges into constraints.
                    for f in &act_fields {
                        if let Some(inline) = &f.inline_constraint {
                            constraints.push(Constraint {
                                name: None,
                                expr: inline.clone(),
                                is_default: false,
                                is_disable: false,
                            });
                        }
                    }
                    act_fields.shrink_to_fit();
                    let activity = obj_get(ao, "activity").map(build_activity).transpose()?;
                    actions.insert(
                        aname.clone(),
                        Action {
                            name: aname.clone(),
                            base: obj_get(ao, "base").and_then(|v| v.as_str()).map(|s| s.to_string()),
                            is_abstract: obj_get(ao, "abstract")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false),
                            fields: act_fields,
                            constraints,
                            execs: Vec::new(),
                            activity,
                            owner: Some(name.clone()),
                        },
                    );
                    action_names.push(aname.clone());
                }
            }
            let mut pools = Vec::new();
            if let Some(ps) = obj_get(co, "pools").and_then(|v| v.as_arr()) {
                for p in ps {
                    if let Some(po) = p.as_obj() {
                        pools.push(Pool {
                            name: obj_get(po, "name").and_then(|v| v.as_str()).unwrap_or("pool").to_string(),
                            type_name: obj_get(po, "type").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                            count: obj_get(po, "count").and_then(|v| v.as_i64()),
                        });
                    }
                }
            }
            let mut binds = Vec::new();
            if let Some(bs) = obj_get(co, "binds").and_then(|v| v.as_arr()) {
                for b in bs {
                    if let Some(bo) = b.as_obj() {
                        binds.push(Bind {
                            pool: obj_get(bo, "pool").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                            wildcard: obj_get(bo, "wildcard").and_then(|v| v.as_bool()).unwrap_or(true),
                            target: obj_get(bo, "target").and_then(|v| v.as_str()).map(|s| s.to_string()),
                        });
                    }
                }
            }
            model.components.insert(
                name.clone(),
                Component {
                    reg_value_type: None,
                    reg_access: "READWRITE".to_string(),
                    reg_size: None,
                    name: name.clone(),
                    base: obj_get(co, "base").and_then(|v| v.as_str()).map(|s| s.to_string()),
                    subcomponents,
                    fields,
                    actions: action_names,
                    pools,
                    binds,
                    execs: Vec::new(),
                    constraints: Vec::new(),
                },
            );
        }
    }
    model.actions = actions;
    model.top = obj_get(obj, "top")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .or_else(|| {
            if model.components.contains_key("pss_top") {
                Some("pss_top".to_string())
            } else {
                model.components.keys().next().cloned()
            }
        });

    Ok(model)
}

/// Classify a type name against the model's enums, types and components.
fn classify(
    type_name: &str,
    enums: &HashMap<String, Vec<String>>,
    types: &HashMap<String, DataType>,
    component_names: &[String],
) -> TypeCategory {
    let leaf = type_name.rsplit("::").next().unwrap_or(type_name);
    if matches!(
        leaf,
        "int" | "bit" | "bool" | "byte" | "shortint" | "longint" | "integer" | "uint"
    ) {
        return TypeCategory::Scalar;
    }
    if let Some(v) = enums.get(leaf) {
        return TypeCategory::Enum(v.clone());
    }
    if types.contains_key(leaf) {
        return TypeCategory::Struct(leaf.to_string());
    }
    if component_names.iter().any(|n| n == leaf) {
        return TypeCategory::Component(leaf.to_string());
    }
    if leaf.ends_with("_h") || leaf.contains("handle") {
        return TypeCategory::Handle;
    }
    TypeCategory::Unknown
}

fn build_fields(
    obj: &[(String, Json)],
    enums: &HashMap<String, Vec<String>>,
    types: &HashMap<String, DataType>,
    component_names: &[String],
) -> PssResult<Vec<Field>> {
    let mut out = Vec::new();
    let arr = match obj_get(obj, "fields").and_then(|v| v.as_arr()) {
        Some(a) => a,
        None => return Ok(out),
    };
    for fv in arr {
        let fo = fv.as_obj().ok_or_else(|| PssError::plain("field must be an object"))?;
        let name = obj_get(fo, "name")
            .and_then(|v| v.as_str())
            .ok_or_else(|| PssError::plain("field requires a `name`"))?
            .to_string();
        let type_name = obj_get(fo, "type").and_then(|v| v.as_str()).unwrap_or("int").to_string();
        let kind = match obj_get(fo, "kind").and_then(|v| v.as_str()).unwrap_or("plain") {
            "rand" => FieldKind::Rand,
            "input" => FieldKind::Input,
            "output" => FieldKind::Output,
            "lock" => FieldKind::Lock,
            "share" => FieldKind::Share,
            _ => FieldKind::Plain,
        };
        let bits = obj_get(fo, "bits").and_then(|v| v.as_i64());
        let inline_constraint = obj_get(fo, "in").and_then(|v| v.as_arr()).and_then(|a| {
            if a.len() == 2 {
                Some(Expr::InRange(
                    Box::new(Expr::Path(Path::simple(name.clone()))),
                    Box::new(Expr::Int(a[0].as_i64().unwrap_or(0))),
                    Box::new(Expr::Int(a[1].as_i64().unwrap_or(0))),
                ))
            } else {
                None
            }
        });
        out.push(Field {
            init: None,
            elem_type: None,
            elem_bits: None,
            name,
            kind,
            type_name: type_name.clone(),
            category: classify(&type_name, enums, types, component_names),
            bits,
            inline_constraint,
            array: obj_get(fo, "array").and_then(|v| v.as_i64()),
        });
    }
    Ok(out)
}

fn build_constraints(obj: &[(String, Json)]) -> PssResult<Vec<Constraint>> {
    let mut out = Vec::new();
    if let Some(arr) = obj_get(obj, "constraints").and_then(|v| v.as_arr()) {
        for c in arr {
            if let Some(s) = c.as_str() {
                out.push(Constraint {
                    name: None,
                    expr: parse_expression(s)?,
                    is_default: false,
                    is_disable: false,
                });
            }
        }
    }
    Ok(out)
}

fn build_activity(v: &Json) -> PssResult<Activity> {
    let arr = v.as_arr().ok_or_else(|| PssError::plain("activity must be an array"))?;
    let mut stmts = Vec::new();
    for item in arr {
        stmts.push(build_activity_stmt(item)?);
    }
    Ok(Activity::Sequence(stmts))
}

/// Build a list of parallel/schedule/select branches — one per array element.
fn build_branches(v: &Json) -> PssResult<Vec<Activity>> {
    let arr = v
        .as_arr()
        .ok_or_else(|| PssError::plain("parallel/schedule/select must be an array"))?;
    let mut out = Vec::new();
    for item in arr {
        out.push(Activity::Sequence(vec![build_activity_stmt(item)?]));
    }
    Ok(out)
}

fn build_activity_stmt(item: &Json) -> PssResult<ActivityStmt> {
    if let Some(s) = item.as_str() {
        return Ok(ActivityStmt::Do(path_from(s)));
    }
    let o = item
        .as_obj()
        .ok_or_else(|| PssError::plain("activity item must be a string or object"))?;
    if let Some(a) = obj_get(o, "do").and_then(|v| v.as_str()) {
        return Ok(ActivityStmt::Do(path_from(a)));
    }
    if let Some(b) = obj_get(o, "parallel") {
        return Ok(ActivityStmt::Parallel {
            branches: build_branches(b)?,
            join: JoinSpec::All,
        });
    }
    if let Some(b) = obj_get(o, "schedule") {
        return Ok(ActivityStmt::Schedule {
            branches: build_branches(b)?,
            join: JoinSpec::All,
        });
    }
    if let Some(b) = obj_get(o, "select") {
        return Ok(ActivityStmt::Select(
            build_branches(b)?.into_iter().map(|a| (None, a)).collect(),
        ));
    }
    if let Some(b) = obj_get(o, "atomic") {
        return Ok(ActivityStmt::Atomic(build_activity(b)?));
    }
    if let Some(b) = obj_get(o, "repeat") {
        let n = obj_get(o, "count").and_then(|v| v.as_i64()).unwrap_or(1);
        return Ok(ActivityStmt::Repeat {
            count: Expr::Int(n),
            index: None,
            body: build_activity(b)?,
            is_replicate: false,
        });
    }
    Err(PssError::plain("unrecognised activity item in JSON model"))
}

/// Build a path from a string, splitting `Component::action` on `::`.
fn path_from(s: &str) -> Path {
    Path::new(s.split("::").map(|p| p.trim().to_string()).collect())
}

fn obj_get<'a>(obj: &'a [(String, Json)], key: &str) -> Option<&'a Json> {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

// ---------------------------------------------------------------------------
// Minimal JSON parser (no external dependencies)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    pub fn parse(src: &str) -> PssResult<Json> {
        let mut p = JsonParser {
            chars: src.chars().collect(),
            pos: 0,
        };
        p.skip_ws();
        let v = p.value()?;
        p.skip_ws();
        if p.pos != p.chars.len() {
            return Err(PssError::plain("trailing characters after JSON value"));
        }
        Ok(v)
    }

    pub fn as_obj(&self) -> Option<&[(String, Json)]> {
        match self {
            Json::Obj(o) => Some(o),
            _ => None,
        }
    }
    pub fn as_arr(&self) -> Option<&[Json]> {
        match self {
            Json::Arr(a) => Some(a),
            _ => None,
        }
    }
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Json::Str(s) => Some(s),
            _ => None,
        }
    }
    pub fn as_i64(&self) -> Option<i64> {
        match self {
            Json::Num(n) => Some(*n as i64),
            Json::Bool(b) => Some(if *b { 1 } else { 0 }),
            _ => None,
        }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Json::Bool(b) => Some(*b),
            _ => None,
        }
    }
}

struct JsonParser {
    chars: Vec<char>,
    pos: usize,
}

impl JsonParser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }
    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(c) if c.is_whitespace()) {
            self.bump();
        }
    }
    fn value(&mut self) -> PssResult<Json> {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.object(),
            Some('[') => self.array(),
            Some('"') => Ok(Json::Str(self.string()?)),
            Some('t') | Some('f') => self.boolean(),
            Some('n') => self.null(),
            Some(c) if c == '-' || c.is_ascii_digit() => self.number(),
            _ => Err(PssError::plain("unexpected token in JSON")),
        }
    }
    fn object(&mut self) -> PssResult<Json> {
        self.bump(); // {
        let mut out = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') {
            self.bump();
            return Ok(Json::Obj(out));
        }
        loop {
            self.skip_ws();
            let key = self.string()?;
            self.skip_ws();
            if self.bump() != Some(':') {
                return Err(PssError::plain("expected `:` in JSON object"));
            }
            let val = self.value()?;
            out.push((key, val));
            self.skip_ws();
            match self.bump() {
                Some(',') => continue,
                Some('}') => break,
                _ => return Err(PssError::plain("expected `,` or `}` in JSON object")),
            }
        }
        Ok(Json::Obj(out))
    }
    fn array(&mut self) -> PssResult<Json> {
        self.bump(); // [
        let mut out = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') {
            self.bump();
            return Ok(Json::Arr(out));
        }
        loop {
            let v = self.value()?;
            out.push(v);
            self.skip_ws();
            match self.bump() {
                Some(',') => continue,
                Some(']') => break,
                _ => return Err(PssError::plain("expected `,` or `]` in JSON array")),
            }
        }
        Ok(Json::Arr(out))
    }
    fn string(&mut self) -> PssResult<String> {
        self.skip_ws();
        if self.bump() != Some('"') {
            return Err(PssError::plain("expected string in JSON"));
        }
        let mut s = String::new();
        loop {
            match self.bump() {
                None => return Err(PssError::plain("unterminated JSON string")),
                Some('"') => break,
                Some('\\') => {
                    let e = self.bump().ok_or_else(|| PssError::plain("bad escape"))?;
                    s.push(match e {
                        'n' => '\n',
                        't' => '\t',
                        'r' => '\r',
                        'b' => '\u{8}',
                        'f' => '\u{c}',
                        '/' => '/',
                        '\\' => '\\',
                        '"' => '"',
                        'u' => {
                            let hex: String = (0..4).filter_map(|_| self.bump()).collect();
                            char::from_u32(u32::from_str_radix(&hex, 16).unwrap_or(0)).unwrap_or('?')
                        }
                        other => other,
                    });
                }
                Some(c) => s.push(c),
            }
        }
        Ok(s)
    }
    fn number(&mut self) -> PssResult<Json> {
        let start = self.pos;
        if self.peek() == Some('-') {
            self.bump();
        }
        while matches!(self.peek(), Some(c) if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-') {
            self.bump();
        }
        let text: String = self.chars[start..self.pos].iter().collect();
        text.parse::<f64>()
            .map(Json::Num)
            .map_err(|_| PssError::plain(format!("invalid JSON number `{}`", text)))
    }
    fn boolean(&mut self) -> PssResult<Json> {
        if self.chars[self.pos..].starts_with(&['t', 'r', 'u', 'e']) {
            self.pos += 4;
            Ok(Json::Bool(true))
        } else if self.chars[self.pos..].starts_with(&['f', 'a', 'l', 's', 'e']) {
            self.pos += 5;
            Ok(Json::Bool(false))
        } else {
            Err(PssError::plain("invalid JSON literal"))
        }
    }
    fn null(&mut self) -> PssResult<Json> {
        if self.chars[self.pos..].starts_with(&['n', 'u', 'l', 'l']) {
            self.pos += 4;
            Ok(Json::Null)
        } else {
            Err(PssError::plain("invalid JSON literal"))
        }
    }
}
